from __future__ import absolute_import
import re
from datetime import datetime, timedelta
import io
from robot.api import logger

RESET_REGEX_PATTERNS = {

    "wcdma": {

        "reset_sm": [
            (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
             r"ResetRequest sent to SYSM.*")],

        "sw_activation": [

            (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
             r"Received evResetRequest with resetCause SWActivation.*"),

            (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
             r"received evResetRequest with " +
             r"resetCoverage=0, resetCause=SWActivation.*")],

        "unblock_sm": [
            (r"[^\n]+\s(\d{2}:\d{2}:\d{2})[^\n]+" +
             "Received evResetRequest with resetCause.*")]
    },

    "lte": {

        "reset_sm": [
            r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
            r"\[sem::MessageDispatcher\] Dispatching message 'ResetRequest'.*"]
    }
}

CELL_REGEX_PATTERNS = {

    "wcdma": [
        (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
         r"cellId:[^\n]+, setOnAirState\(\), isOnAir: 1.*"),

        (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})" +
         r"[^\n]+BTS Status is now OnAir.*")],

    "lte": [
        (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
         r"changed to [oO]nAirDone from [vV]alidated.*"),

        (r"\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
         r"changed from [vV]alidated to [oO]nAirDone.*")]
}

FPGA_UPDATE_PATTERNS = {

    "sbts" : [
        ("\d{2}.\d{2}\s(\d{2}:\d{2}:\d{2})[^\n]+" +
        "About to call ddal_fpga_update_mod.*")
    ]

}

POWER_MESSAGE_PATTERN = {
    "LTE_ASIA": "(\d{2}.\d{2}\s\d{2}:\d{2}:\d{2}\.\d+).*RX.*lnCelId\s(\d+).*per\santenna\:(.*)"
}


class SysLog(object):
    """

    """

    def __init__(self):
        super(SysLog, self).__init__()


    def get_reset_time(self, syslog_file_path, tech, trigger):
        """
        Keyword for diff time between reset trigger and first OnAir cell times.

        | **Author:** catalin.chiorean@nokia.com
        | **Maintainer:** catalin.chiorean@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | This method parses BTS UDP syslog file provided via
        | parameter and search for Reset request in case of
        | different triggers and Cells State change to OnaAir events.
        | Than, computes elapsed time between Reset
        | trigger and First Cell OnAir state change.
        | Parameter 'trigger' can be 'reset_sm', 'unblock_sm', 'sw_activation'
        | for tech = 'wcdma' and 'reset_sm' fro tech = 'lte'.

        **Input Parameters:**

        +--------------------+--------+------------------------------+
        | Input Parameters   | Man.   | Description                  |
        +====================+========+==============================+
        | syslog_file_path   | Yes    | Absolute path to syslog file |
        +--------------------+--------+------------------------------+
        | tech               | Yes    | Can be 'wcdma' or 'lte'      |
        +--------------------+--------+------------------------------+
        | trigger            | Yes    | reset trigger                |
        +--------------------+--------+------------------------------+

        **Examples:**

        .. code-block:: robotframework

           ${reset_results_list}     Get Reset Time  /home/ute/logs/MasterUDP
           ...  wcdma  reset_sm
           ${reset_results_list}     Get Reset Time  /home/ute/logs/MasterUDP
           ...  wcdma  unblock_sm
           ${reset_results_list}     Get Reset Time  /home/ute/logs/MasterUDP
           ...  wcdma  sw_activation
           ${reset_results_list}     Get Reset Time  /home/ute/logs/MasterUDP
           ...  lte    reset_sm

           # Result:
           ${reset_results_list} = [272, 268, 266]

        | **Return value:**
        | reset_time_list: list with duration of the resets,
        | elapsed time in seconds between
        | Reset trigger and first cell state change to OnAir state.
        | Empty list if there is no reset trigger or
        | cell state change to enabled.
        """

        reset_match, cell_match = self._check_param_get_reset_time(tech,
                                                                   trigger)
        reset_list = self._parse_syslog_for_resets(cell_match, reset_match,
                                                   syslog_file_path)
        return self._calculate_reset_times(reset_list)

    def _load_syslog(self, syslog_file_path):
        try:
            with io.open(syslog_file_path, 'r', errors="ignore") as f:
                syslog_file_lines = f.readlines()
            return syslog_file_lines
        except IOError:
            logger.error(
                "Cannot get info from syslog file "
                "because of IOError. TC ended.")
            raise
        except Exception:
            logger.error("Unexpected error. TC ended.")
            raise

    def _check_param_get_reset_time(self, tech, trigger):
        try:
            return (RESET_REGEX_PATTERNS[tech][trigger],
                    CELL_REGEX_PATTERNS[tech])
        except KeyError as e:
            logger.error("Wrong parameters. KW ended")
            raise ValueError("Wrong parameters: {}".format(str(e)))

    def _parse_syslog_for_resets(self, cell_match, reset_match,
                                 syslog_file_path):
        reset_found = False
        reset_request_timestamp = None
        records_for_reset = []
        reset_list = []
        try:
            with io.open(syslog_file_path, 'r', errors="ignore") as file:
                for line in file:
                    match_reset = self._get_matching_resets(line, reset_match)
                    if match_reset:
                        reset_request_timestamp = match_reset[0].group(1)
                        reset_found = True
                        records_for_reset = []
                    else:
                        if not records_for_reset:
                            records_for_reset = \
                                self._add_records_having_matching_cells_to_resets_list(
                                    cell_match,
                                    records_for_reset, line,
                                    reset_found, reset_request_timestamp)
                            if records_for_reset:
                                reset_list.append(records_for_reset)
                return reset_list
        except IOError:
            logger.error(
                "Cannot get info from syslog file "
                "because of IOError. TC ended.")
            raise
        except Exception:
            logger.error("Unexpected error. TC ended.")
            raise

    def _add_records_having_matching_cells_to_resets_list(
            self, cell_match, cells_onair_timestamp_found, line, reset_found,
            reset_request_timestamp):

        match_cell = self._get_matching_resets(line, cell_match)
        if (match_cell and reset_found
                and not cells_onair_timestamp_found):
            return (reset_request_timestamp, match_cell[0].group(1))
        return ()

    def _get_matching_resets(self, line, reset_match):
        match_reset = [re.match(regex, line) for regex in reset_match]
        return [mr for mr in match_reset if mr]

    def _calculate_reset_times(self, reset_list):
        FMT = '%H:%M:%S'
        reset_time_list = []
        for items in reset_list:
            start = datetime.strptime(items[0], FMT)
            end = datetime.strptime(items[1], FMT)
            if start <= end:  # e.g., 10:33:26-11:15:49
                tdelta = end - start
                reset_time_list.append(tdelta.seconds)
            else:  # end < start e.g., 23:55:00-00:25:00
                end += timedelta(1)
                assert end > start
                tdelta = end - start
                reset_time_list.append(tdelta.seconds)
        return reset_time_list

    def syslog_contains(self, syslog_file_path, requested_string):
        """
        Keyword for determining string match within syslog.

        | **Author:** piotr.stuglik@nokia.com
        | **Maintainer:** piotr.stuglik@nokia.com
        | **Released with version:** 3.6.0

        | **Full description:**
        | Checks whether syslog contains requested string.

        **Input Parameters:**

        +--------------------+--------+--------------------------------+
        | Input Parameters   | Man.   | Description                    |
        +====================+========+================================+
        | syslog_file_path   | Yes    | Absolute path to syslog file.  |
        +--------------------+--------+--------------------------------+
        | requested_string   | Yes    | String to look for in the log. |
        +--------------------+--------+--------------------------------+

        **Examples:**

        .. code-block:: robotframework

           ${syslog_contains_muting_msgs}     Syslog Contains  /home/ute/logs/MasterUDP
           ...  muting messages

           # Result:
           ${syslog_contains_muting_msg} = True

        | **Return value:**
        | -  bool
        """

        syslog_file_lines = self._load_syslog(syslog_file_path)
        for line in syslog_file_lines:
            if line.find(requested_string) != -1:
                return True
        return False

    def syslog_contains_regex(self, syslog_file_path, requested_regex):
        """
        Keyword for determining if a regex match within syslog.

        | **Author:** alexandru.stamp@nokia.com
        | **Maintainer:** alexandru.stamp@nokia.com

        | **Full description:**
        | Checks whether syslog contains the requested regular expression.

        **Input Parameters:**

        +--------------------+--------+--------------------------------+
        | Input Parameters   | Man.   | Description                    |
        +====================+========+================================+
        | syslog_file_path   | Yes    | Absolute path to syslog file.  |
        +--------------------+--------+--------------------------------+
        | requested_regex   | Yes     | Regex  to look for in the log. |
        +--------------------+--------+--------------------------------+

        **Examples:**

        .. code-block:: robotframework

           ${syslog_contains_muting_msgs}     Syslog Contains Regex  /home/ute/logs/MasterUDP
           ...  [0-9][a-zA-Z]*

           # Result:
           ${syslog_contains_muting_msg} = True

        | **Return value:**
        | -  bool
        """

        syslog_file_lines = self._load_syslog(syslog_file_path)
        for line in syslog_file_lines:
            if re.search(requested_regex, line) is not None:
                return True
        return False

    def _check_param_get_fpga_update_status(self, tech):
        try:
            return FPGA_UPDATE_PATTERNS[tech]
        except KeyError as e:
            logger.error("Wrong parameters. KW ended")
            raise ValueError("Wrong parameters: {}".format(str(e)))

    def _get_matching_fpga_update_status(self, line, fpga_match):
        for regex in fpga_match:
            if re.match(regex,line) is not None:
                return True
        return False

    def _parse_syslog_for_fpga_update_status(self, fpga_match, syslog_file_path):
        fpga_update_found = False
        try:
            with io.open(syslog_file_path, 'r', errors="ignore") as file:
                for line in file:
                    fpga_update_found = self._get_matching_fpga_update_status(line, fpga_match)
                    if fpga_update_found is True:
                        return True
            return False
        except IOError:
            logger.error(
                "Cannot get info from syslog file "
                "because of IOError. TC ended.")
            raise
        except Exception:
            logger.error("Unexpected error. TC ended.")
            raise

    def get_fpga_update_status(self, syslog_file_path, tech):
        """
        Keyword for determining if a FPGA update occurred

        | **Author:** alexandru.stamp@nokia.com
        | **Maintainer:** alexandru.stamp@nokia.com
        | **Released with version:** 3.9.0

        | **Full description:**
        | Check if a FPGA Uppdate occured. This method parses BTS UDP log
        | and returns True or False if a FPGA Update occured.

        **Input Parameters:**

        +--------------------+--------+--------------------------------+
        | Input Parameters   | Man.   | Description                    |
        +====================+========+================================+
        | syslog_file_path   | Yes    | Absolute path to syslog file.  |
        +--------------------+--------+--------------------------------+
        | tech               | Yes    | Technology       e.g. sbts     |
        +--------------------+--------+--------------------------------+

        **Examples:**

        .. code-block:: robotframework

           ${fpga_update_status}     Get FPGA Update Status  /home/ute/logs/
           ...  sbts

           # Result:
           ${fpga_update_status} = True

        | **Return value:**
        | -  bool
        """
        fpga_match = self._check_param_get_fpga_update_status(tech)
        update_status = self._parse_syslog_for_fpga_update_status(fpga_match, syslog_file_path)
        return update_status

    def get_cell_measurements(self, syslog_file_path, tech, start_with_line):
        """
        Keyword for returning cell measurements and timestamp of the measurement

        | **Author:** alexandru.stamp@nokia.com
        | **Maintainer:** alexandru.stamp@nokia.com
        | **Released with version:** 3.11.0

        | **Full description:**
        | Check if cell RX power measurement lines are present in the syslog
        | and returns the cells ids, a power list and timestamp. This KW also returns the length of the syslog

        **Input Parameters:**

        +--------------------+--------+-------------------------------------+
        | Input Parameters   | Man.   | Description                         |
        +====================+========+=====================================+
        | syslog_file_path   | Yes    | Absolute path to syslog file.       |
        +--------------------+--------+-------------------------------------+
        | tech               | Yes    | Technology       e.g. LTE_ASIA      |
        +--------------------+--------+-------------------------------------+
        | start_with_line    | Yes    | With what line should parsing start |
        +--------------------+--------+-------------------------------------+

        **Examples:**

        .. code-block:: robotframework

           ${cell_measurements}     Get Cell Measurements  /home/ute/logs/UDPLog  LTE_ASIA  0

           # Result:
           ${cell_measurement_dict}  ${syslog_lines}= ({'46408': {'powerlist': ['-118.78', '-118.91'], 'timestamp': '31.08 05:52:35.215965'}}, 212)

        | **Return value:**
        | -  bool
        """
        regex_match = self._check_param_get_cell_measurements(tech)
        return self._parse_syslog_for_cell_measurement_string(syslog_file_path, regex_match, start_with_line)

    def _parse_syslog_for_cell_measurement_string(self, syslog_file, regex_match, starting_line):

        cell_power_dict = {}
        line_number = 0
        try:
            with io.open(syslog_file, 'r', errors="ignore") as f:
                for line_number, syslog_line in enumerate(f, start=1):
                    if line_number < starting_line:
                        continue
                    match = re.search(regex_match, syslog_line)
                    if match is not None:
                        processed_string = self._process_cell_measurement_string(match)
                        cell_power_dict[processed_string[0]] = {}
                        cell_power_dict[processed_string[0]]["powerlist"] = processed_string[1]
                        cell_power_dict[processed_string[0]]["timestamp"] = processed_string[2]
        except IOError:
            logger.error(
                "Cannot get info from syslog file "
                "because of IOError. TC ended.")
            raise
        except Exception:
            logger.error("Unexpected error. TC ended.")
            raise

        return cell_power_dict, line_number

    def _process_cell_measurement_string(self, matched_string):

        powers_list = matched_string.group(3).replace(" ", "").split(",")
        powers_list = [value for value in powers_list if value not in ['-140.00', '-Inf', '0.00']]

        return matched_string.group(2), powers_list, matched_string.group(1)  # CELL_ID, POWER_LIST, TIMESTAMP

    def _check_param_get_cell_measurements(self, tech):
        try:
            return POWER_MESSAGE_PATTERN[tech]
        except KeyError as e:
            logger.error("Wrong parameters. KW ended")
            raise ValueError("Wrong parameters: {}".format(str(e)))
